27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    public String getEmail() {
112	        return this.email;
113	    }
114	
115	    public void setEmail(String email) {
116	        this.email = email;
117	    }
118	
119	    public String getPostcode() {
120	        return this.postcode;
121	    }
122	
123	    public void setPostcode(String postcode) {
124	        this.postcode = postcode;
125	    }
126	
127	    public LocalDate getRegistrationDate() {
128	        return this.registrationDate;
129	    }
130	
131	    public void setRegistrationDate(LocalDate registrationDate) {
132	        this.registrationDate = registrationDate;
133	    }
134	
135	    public LocalDate getBirthDate() {
136	        return this.birthDate;
137	    }
138	
139	    public void setBirthDate(LocalDate birthDate) {
140	        this.birthDate = birthDate;
141	    }
142	
143	    /**
144	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
145	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
146	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
147	     *
148	     * @return the age band, or {@code null} when either the birth date or the registration
149	     *         date has not been assigned
150	     */
151	    public String getAgeBand() {
152	        if (this.birthDate == null || this.registrationDate == null) {
153	            return null;
154	        }
155	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
156	        if (age < 18) {
157	            return "MINOR";
158	        }
159	        if (age < 65) {
160	            return "ADULT";
161	        }
162	        return "SENIOR";
163	    }
164	
165	    public String getCustomerCode() {
166	        return this.customerCode;
167	    }
168	
169	    public void setCustomerCode(String customerCode) {
170	        this.customerCode = customerCode;
171	    }
172	
173	    public String getHouseholdId() {
174	        return this.householdId;
175	    }
176	
177	    public void setHouseholdId(String householdId) {
178	        this.householdId = householdId;
179	    }
180	
181	    public Integer getNamesakeCount() {
182	        return this.namesakeCount;
183	    }
184	
185	    public void setNamesakeCount(Integer namesakeCount) {
186	        this.namesakeCount = namesakeCount;
187	    }
188	
189	    /**
190	     * Whether more than 80 owners had already been created today at the time this owner
191	     * was created, indicating an unusually high signup volume.
192	     *
193	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
194	     *         {@code false} (never {@code null})
195	     */
196	    public Boolean getBulkSignupWarning() {
197	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
198	    }
199	
200	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
201	        this.bulkSignupWarning = bulkSignupWarning;
202	    }
203	
204	    /**
205	     * The number of owners in this owner's household (owners sharing the same
206	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
207	     * membership tier.
208	     *
209	     * @return the household member count, or {@code null} if it has not been assigned
210	     */
211	    public Integer getHouseholdSize() {
212	        return this.householdSize;
213	    }
214	
215	    public void setHouseholdSize(Integer householdSize) {
216	        this.householdSize = householdSize;
217	    }
218	
219	    /**
220	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
221	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
222	     *
223	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
224	     *         {@code false} (never {@code null})
225	     */
226	    public Boolean getPossibleDuplicate() {
227	        return this.possibleDuplicate != null && this.possibleDuplicate;
228	    }
229	
230	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
231	        this.possibleDuplicate = possibleDuplicate;
232	    }
233	
234	    /**
235	     * The id of the existing owner this owner may duplicate (same last name and postcode,
236	     * different telephone), or {@code null} when this owner is not a possible duplicate.
237	     *
238	     * @return the matching owner id, or {@code null}
239	     */
240	    public Integer getPossibleDuplicateOf() {
241	        return this.possibleDuplicateOf;
242	    }
243	
244	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
245	        this.possibleDuplicateOf = possibleDuplicateOf;
246	    }
247	
248	    /**
249	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
250	     *
251	     * @return the formatted display name
252	     */
253	    public String getDisplayName() {
254	        return this.getLastName() + ", " + this.getFirstName();
255	    }
256	
257	    /**
258	     * The owner's initials: the upper-cased first letters of the first and last
259	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
260	     *
261	     * @return the formatted initials
262	     */
263	    public String getInitials() {
264	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
265	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
266	    }
267	
268	    /**
269	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
270	     * {@code YY} is the last two digits of the registration date's year (e.g.
271	     * {@code "NSW-1A2B3C4D-M26"}).
272	     *
273	     * @return the formatted membership number, or {@code null} if the customer code or
274	     *         registration date has not been assigned
275	     */
276	    public String getMembershipNumber() {
277	        if (this.customerCode == null || this.registrationDate == null) {
278	            return null;
279	        }
280	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
281	    }
282	
283	    /**
284	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
285	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
286	     * (non-digit characters are ignored).
287	     *
288	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
289	     */
290	    public Integer getCheckDigit() {
291	        if (this.customerCode == null) {
292	            return null;
293	        }
294	        int sum = 0;
295	        boolean dbl = true;
296	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
297	            char c = this.customerCode.charAt(i);
298	            if (c < '0' || c > '9') {
299	                continue;
300	            }
301	            int d = c - '0';
302	            if (dbl) {
303	                d *= 2;
304	                if (d > 9) {
305	                    d -= 9;
306	                }
307	            }
308	            sum += d;
309	            dbl = !dbl;
310	        }
311	        return (10 - (sum % 10)) % 10;
312	    }
313	
314	    /**
315	     * The owner's numeric membership level, from {@code 1} to {@code 3}, computed on
316	     * creation. It starts at {@code 1}, gains {@code 1} when this owner carries an email
317	     * address, gains {@code 1} when this owner has no namesakes ({@code namesakeCount} is
318	     * {@code 0}), and is capped at {@code 3} (level {@code 4} is reserved for tenure).
319	     *
320	     * @return the membership level
321	     */
322	    public Integer getMembershipLevel() {
323	        int level = 1;
324	        boolean hasEmail = this.email != null && !this.email.isBlank();
325	        if (hasEmail) {
326	            level++;
327	        }
328	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
329	        if (noNamesakes) {
330	            level++;
331	        }
332	        return Math.min(level, 3);
333	    }
334	
335	    /**
336	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
337	     * email address, otherwise {@code "PHONE"}.
338	     *
339	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
340	     */
341	    public String getContactPreference() {
342	        boolean hasEmail = this.email != null && !this.email.isBlank();
343	        return hasEmail ? "EMAIL" : "PHONE";
344	    }
345	
346	    /**
347	     * The owner's identity key: the single derived value used for duplicate detection, formed as
348	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
349	     * email are the already-normalized stored values and a {@code null} email or household id is
350	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
351	     * are equal; because the telephone is part of the key, household members with different
352	     * telephones have different identity keys.
353	     *
354	     * @return the derived identity key
355	     */
356	    public String getIdentityKey() {
357	        String telephonePart = this.telephone == null ? "" : this.telephone;
358	        String emailPart = this.email == null ? "" : this.email;
359	        String householdPart = this.householdId == null ? "" : this.householdId;
360	        return telephonePart + "|" + emailPart + "|" + householdPart;
361	    }
362	
363	    /**
364	     * City -> canonical region, the fixed ground truth for deriving locality.
365	     */
366	    private static final Map<String, String> CITY_REGION = Map.of(
367	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
368	
369	    /**
370	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
371	     * deriving locality from the postcode ahead of the city.
372	     */
373	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
374	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
375	
376	    /**
377	     * The owner's locality: the canonical region resolved by the postcode range first
378	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
379	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
380	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
381	     * when the city is not in the table either. The postcode takes precedence so cities that share a
382	     * name are disambiguated by their postcode's region.
383	     *
384	     * @return the canonical region string, or {@code "UNKNOWN"}
385	     */
386	    public String getLocality() {
387	        String byPostcode = regionForPostcode(this.postcode);
388	        if (byPostcode != null) {
389	            return byPostcode;
390	        }
391	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
392	    }
393	
394	    /**
395	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
396	     * absent, not a 4-digit number, or in no known range.
397	     *
398	     * @param postcode the owner's postcode (may be {@code null})
399	     * @return the matching region, or {@code null}
400	     */
401	    private static String regionForPostcode(String postcode) {
402	        if (postcode == null || !postcode.matches("\\d{4}")) {
403	            return null;
404	        }
405	        int value = Integer.parseInt(postcode);
406	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
407	            int[] range = entry.getValue();
408	            if (value >= range[0] && value <= range[1]) {
409	                return entry.getKey();
410	            }
411	        }
412	        return null;
413	    }
414	
415	    protected Set<Pet> getPetsInternal() {
416	        if (this.pets == null) {
417	            this.pets = new HashSet<>();
418	        }
419	        return this.pets;
420	    }
421	
422	    protected void setPetsInternal(Set<Pet> pets) {
423	        this.pets = pets;
424	    }
425	
426	    public List<Pet> getPets() {
427	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
428	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
429	        return Collections.unmodifiableList(sortedPets);
430	    }
431	
432	    public void setPets(List<Pet> pets) {
433	        this.pets = new HashSet<>(pets);
434	    }
435	
436	    public void addPet(Pet pet) {
437	        getPetsInternal().add(pet);
438	        pet.setOwner(this);
439	    }
440	
441	    /**
442	     * Return the Pet with the given name, or null if none found for this Owner.
443	     *
444	     * @param name to test
445	     * @return true if pet name is already in use
446	     */
447	    public Pet getPet(String name) {
448	        return getPet(name, false);
449	    }
450	
451	    /**
452	     * Return the Pet with the given name, or null if none found for this Owner.
453	     *
454	     * @param name to test
455	     * @return true if pet name is already in use
456	     */
457	    public Pet getPet(String name, boolean ignoreNew) {
458	        name = name.toLowerCase();
459	        for (Pet pet : getPetsInternal()) {
460	            if (!ignoreNew || !pet.isNew()) {
461	                String compName = pet.getName();
462	                compName = compName.toLowerCase();
463	                if (compName.equals(name)) {
464	                    return pet;
465	                }
466	            }
467	        }
468	        return null;
469	    }
470	
471	    public Pet getPet(Integer petId) {
472	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
473	    }
474	
475	    @Override
476	    public String toString() {
477	        return new ToStringCreator(this)
478	
479	            .append("id", this.getId())
480	            .append("new", this.isNew())
481	            .append("lastName", this.getLastName())
482	            .append("firstName", this.getFirstName())
483	            .append("address", this.address)
484	            .append("city", this.city)
485	            .append("telephone", this.telephone)
486	            .append("email", this.email)
487	            .toString();
488	    }
489	}
