103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
107	    private final PetMapper petMapper;
108	
109	    private final VisitMapper visitMapper;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        LocalDate suppliedDate = owner.getRegistrationDate();
152	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
156	        LocalDate registrationDate = toBusinessDay(effectiveDate);
157	        owner.setRegistrationDate(registrationDate);
158	        long createdToday = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
160	            .count();
161	        if (createdToday >= 100) {
162	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
163	        }
164	        owner.setBulkSignupWarning(createdToday > 80);
165	        String address = normalizeAddress(owner.getAddress());
166	        if (address == null || address.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	        }
169	        owner.setAddress(address);
170	        String telephone = toE164(owner.getTelephone());
171	        if (telephone == null) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setTelephone(telephone);
175	        if (owner.getEmail() != null) {
176	            String email = normalizeEmail(owner.getEmail());
177	            if (!EMAIL_PATTERN.matcher(email).matches()) {
178	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
179	            }
180	            owner.setEmail(email);
181	        }
182	        if (!isPostcodeValidForCity(owner.getPostcode(), owner.getLocality())) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        String cityKey = householdKey(owner.getCity());
186	        long cityCount = this.clinicService.findAllOwners().stream()
187	            .filter(existing -> existing.getCity() != null
188	                && cityKey.equals(householdKey(existing.getCity())))
189	            .count();
190	        if (cityCount >= 50) {
191	            return new ResponseEntity<>(HttpStatus.CONFLICT);
192	        }
193	        // The household is keyed on (normalized last name, postcode): every owner derives the same
194	        // deterministic householdId from those two fields, so owners sharing them are the same
195	        // household. This computed id is what duplicate detection and the household size below key off.
196	        String householdId = householdId(owner);
197	        owner.setHouseholdId(householdId);
198	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
199	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
200	            .toList();
201	        owner.setHouseholdSize(householdMembers.size() + 1);
202	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
203	        // Household-duplicate block: a second owner in an existing household (same computed
204	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
205	        // declaring the new owner a member — rather than creating the household link itself.
206	        if (!householdMembers.isEmpty() && !sharesHousehold) {
